/**
 * A study session played line by line. See orbt_core::drill for the timing.
 */
public interface DrillSessionInterface {
    
    fun `analysisMoves`(`timing`: SchedTiming, `nowMs`: kotlin.Long): MovesAndChanges
    
    fun `answeredCount`(): kotlin.Long
    
    fun `arrows`(): List<Arrow>
    
    fun `askedKind`(): QueueKind?
    
    fun `browseNode`(`timing`: SchedTiming, `nowMs`: kotlin.Long): NodeAndChanges
    
    fun `checkAgain`(`timing`: SchedTiming)
    
    fun `correctCount`(): kotlin.Long
    
    fun `counts`(): Counts
    
    fun `currentNode`(): kotlin.UInt?
    
    fun `extendLimits`(`new`: kotlin.Long, `review`: kotlin.Long, `timing`: SchedTiming): Changes
    
    fun `feedback`(): Feedback
    
    fun `hint`(`timing`: SchedTiming, `nowMs`: kotlin.Long): Changes
    
    fun `isFiltered`(): kotlin.Boolean
    
    fun `isUserTurn`(): kotlin.Boolean
    
    fun `lastMove`(): PlayedMove?
    
    fun `line`(): StudyLineRecord?
    
    fun `nextLearningDue`(): kotlin.Long?
    
    fun `nextLine`(`timing`: SchedTiming)
    
    fun `phase`(): Phase
    
    /**
     * The nodes of the moves on the board, from the start of the line.
     */
    fun `playedNodes`(): List<kotlin.UInt>
    
    fun `position`(): Position
    
    fun `showHint`(): kotlin.Boolean
    
    /**
     * Starts the session; `learn_more` new cards are added to today's limit first.
     */
    fun `start`(`learnMore`: kotlin.Long, `timing`: SchedTiming): Changes
    
    /**
     * One step of the rewind or autoplay.
     */
    fun `step`(`nowMs`: kotlin.Long)
    
    fun `studiedMillis`(): kotlin.Long
    
    fun `userMoved`(`from`: BoardSquare, `to`: BoardSquare, `promotion`: PieceKind?, `timing`: SchedTiming, `nowMs`: kotlin.Long): Changes
    
    fun `wrongTimeout`()
    
    companion object
}

