    }
}

/**
 * @suppress
 */
public object FfiConverterTypeExplorerListener: FfiConverter<ExplorerListener, Long> {
    internal val handleMap = UniffiHandleMap<ExplorerListener>()

    override fun lower(value: ExplorerListener): Long {
        if (value is ExplorerListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ExplorerListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ExplorerListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ExplorerListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ExplorerListener) = 8UL

    override fun write(value: ExplorerListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


