/**
 * The cards and review log statistics are computed from.
 */
public interface GraphsInterface {
    
    fun `buttons`(`range`: GraphRange): ButtonCounts
    
    fun `cardCounts`(): CardCounts
    
    fun `cardInfo`(`card`: Card, `epd`: Epd): CardInfo
    
    fun `difficulty`(): Map<kotlin.Long, kotlin.Long>
    
    /**
     * Day → moves answered for the first time that day.
     */
    fun `firstStudied`(): Map<kotlin.Long, kotlin.Long>
    
    fun `futureDue`(): FutureDue
    
    /**
     * Moves due over a range from today (the table under Anki's Future Due graph).
     */
    fun `futureDueSummary`(`range`: GraphRange): FutureDueSummary
    
    fun `hours`(`range`: GraphRange): List<Hour>
    
    fun `intervals`(): Map<kotlin.Long, kotlin.Long>
    
    fun `retrievability`(): Retrievability
    
    fun `reviews`(): Reviews
    
    /**
     * Days studied, answers and time over a range (the table under Anki's Reviews graph).
     */
    fun `reviewsSummary`(`range`: GraphRange): ReviewsSummary
    
    fun `stability`(): Map<kotlin.Long, kotlin.Long>
    
    /**
     * Each day from the first answer: the moves in each stage at its end.
     */
    fun `stagesByDay`(): List<StageCounts>
    
    fun `streak`(): Streak
    
    fun `today`(): Today
    
    /**
     * True retention, of the cards in `positions` if given.
     */
    fun `trueRetention`(`positions`: List<Epd>?): List<RetentionRow>
    
    companion object
}

