    override fun `play`(`from`: BoardSquare, `to`: BoardSquare, `promotion`: PieceKind?): PlayResult? {
            return FfiConverterOptionalTypePlayResult.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
