/**
 * @suppress
 */
public object FfiConverterTypePosition: FfiConverter<Position, Long> {
    override fun lower(value: Position): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Position {
        return Position(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Position {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Position) = 8UL

    override fun write(value: Position, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


