/**
 * An open repertoire. The platform reads and writes its files; see `Changes`.
 */
public interface RepertoireDocInterface {
    
    fun `addLine`(`ucis`: List<kotlin.String>, `start`: kotlin.UInt): AddResult
    
    fun `addMove`(`uci`: kotlin.String, `parent`: kotlin.UInt): AddResult
    
    /**
     * Every node, in id order (for the outline and search).
     */
    fun `allNodes`(): List<Node>
    
    fun `canUndo`(): kotlin.Boolean
    
    fun `card`(`epd`: Epd): Card?
    
    fun `cardEpds`(`root`: kotlin.UInt): List<Epd>
    
    /**
     * Your-turn nodes with a main move under `root`, where cards are asked.
     */
    fun `cardNodes`(`root`: kotlin.UInt): List<kotlin.UInt>
    
    /**
     * The reach of each card position, for expected recall.
     */
    fun `cardReach`(): Map<Epd, kotlin.Double>
    
    fun `cards`(): Map<Epd, Card>
    
    fun `childBySan`(`id`: kotlin.UInt, `san`: kotlin.String): kotlin.UInt?
    
    fun `childByUci`(`id`: kotlin.UInt, `uci`: kotlin.String): kotlin.UInt?
    
    fun `color`(): Side
    
    fun `count`(): kotlin.UInt
    
    fun `coverage`(`id`: kotlin.UInt): NodeCoverage?
    
    fun `coverageRoot`(): NodeCoverage?
    
    fun `database`(): ExplorerDatabase
    
    fun `delete`(`id`: kotlin.UInt): Changes
    
    /**
     * Replies at a position that is not in the repertoire (a draft on the board).
     */
    fun `draftReplies`(`epd`: Epd, `reach`: kotlin.Double?): List<ReplyInfo>?
    
    fun `dueTomorrow`(`timing`: SchedTiming): kotlin.Long
    
    fun `extendLimitsToday`(`new`: kotlin.Long, `review`: kotlin.Long, `timing`: SchedTiming): Changes
    
    /**
     * A gap as a line of moves, e.g. "1. e4 c5 2. Nf3 Nc6".
     */
    fun `gapText`(`gap`: CoverageGap): kotlin.String
    
    /**
     * All gaps, biggest first.
     */
    fun `gaps`(): List<CoverageGap>
    
    /**
     * This repertoire's part of the statistics: of the whole collection (every stored card),
     * or of this repertoire alone (only cards at its positions). `on_disk` is the review log file.
     */
    fun `graphParts`(`onDisk`: kotlin.ByteArray, `wholeCollection`: kotlin.Boolean): GraphParts
    
    fun `isAncestor`(`a`: kotlin.UInt, `b`: kotlin.UInt): kotlin.Boolean
    
    fun `isExcluded`(`uci`: kotlin.String, `node`: kotlin.UInt): kotlin.Boolean
    
    fun `lastLine`(): List<kotlin.String>?
    
    fun `laterLearningDues`(`timing`: SchedTiming): List<kotlin.Long>
    
    fun `learningProgress`(`node`: kotlin.UInt): Progress
    
    fun `leaves`(`id`: kotlin.UInt): List<kotlin.UInt>
    
    fun `limits`(): DeckLimits?
    
    /**
     * SAN line to a node, e.g. "1. e4 c5 2. Nf3".
     */
    fun `lineText`(`id`: kotlin.UInt): kotlin.String
    
    fun `loadWarnings`(): List<kotlin.String>
    
    fun `mergeConflictVersion`(`text`: kotlin.String): Changes
    
    fun `moves`(`id`: kotlin.UInt): List<PlayedMove>
    
    /**
     * Unix seconds when the next card falls due after today's are done.
     */
    fun `nextDue`(`timing`: SchedTiming): kotlin.Long?
    
    fun `node`(`id`: kotlin.UInt): Node?
    
    fun `nodeFollowing`(`ucis`: List<kotlin.String>, `start`: kotlin.UInt): kotlin.UInt?
    
    fun `nodesAt`(`epd`: Epd): List<kotlin.UInt>
    
    /**
     * The opening branches for per-branch statistics.
     */
    fun `openingBranches`(): List<kotlin.UInt>
    
    /**
     * The opening name of a node, or of its nearest ancestor, from stats already loaded.
     */
    fun `openingName`(`id`: kotlin.UInt): kotlin.String?
    
    /**
     * The outline rows below `id`: one per child, each a chain of moves without branching.
     */
    fun `outlineChildren`(`id`: kotlin.UInt): List<OutlineItem>
    
    /**
     * The repertoire's own practice mode, if it overrides the default.
     */
    fun `ownPracticeMode`(): PracticeMode?
    
    /**
     * Node ids from the root to `id`, inclusive.
     */
    fun `path`(`id`: kotlin.UInt): List<kotlin.UInt>
    
    fun `pgnSaved`(`text`: kotlin.String)
    
    fun `pgnToSave`(): kotlin.String?
    
    fun `position`(`id`: kotlin.UInt): Position?
    
    fun `practiceMode`(): PracticeMode
    
    fun `promote`(`id`: kotlin.UInt): Changes
    
    /**
     * How often each position is reached.
     */
    fun `reach`(): Map<kotlin.UInt, kotlin.Double>
    
    fun `remainingLimits`(`timing`: SchedTiming): RemainingLimits
    
    fun `rememberLine`(`ucis`: List<kotlin.String>): Changes
    
    fun `remotePgn`(`text`: kotlin.String): Changes
    
    /**
     * The sidecar changed on disk; reloads stats and recomputes when settings changed.
     */
    fun `remoteSidecar`(`data`: kotlin.ByteArray): Changes
    
    /**
     * The cards stored for this repertoire's positions.
     */
    fun `repertoireCards`(): Map<Epd, Card>
    
    /**
     * Fetches stats for the position on screen, ahead of the coverage check.
     */
    fun `requestStats`(`epd`: Epd, `nowMs`: kotlin.Long)
    
    /**
     * The whole review log: the file's entries plus answers not written yet.
     */
    fun `reviewLog`(`onDisk`: kotlin.ByteArray): List<RevlogEntry>
    
    fun `reviewsBeyondLimit`(`timing`: SchedTiming): kotlin.Long
    
    fun `revision`(): kotlin.ULong
    
    fun `revlogAppended`()
    
    fun `revlogToAppend`(): kotlin.ByteArray?
    
    fun `root`(): Node
    
    fun `savedMoveCount`(): kotlin.Long
    
    /**
     * Nodes whose move (loose SAN) or note matches `query`, shallowest first.
     */
