     * Every stored entry of a database (by its cache key): (EPD, the stats as JSON).
     */
    fun `load`(`databaseKey`: kotlin.String): List<StoredStats>
    
    fun `save`(`databaseKey`: kotlin.String, `epd`: Epd, `json`: kotlin.ByteArray)
    
    companion object
}

/**
 * Where the platform keeps explorer stats between launches (a local, unsynced cache).
 */
open class StatsStoreImpl: Disposable, AutoCloseable, StatsStore
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_opening_core_fn_free_statsstore(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_opening_core_fn_clone_statsstore(handle, status)
        }
    }

    
    /**
     * Every stored entry of a database (by its cache key): (EPD, the stats as JSON).
     */override fun `load`(`databaseKey`: kotlin.String): List<StoredStats> {
            return FfiConverterSequenceTypeStoredStats.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_opening_core_fn_method_statsstore_load(
        it,
        
        FfiConverterString.lower(`databaseKey`),_status)
}
    }
    )
    }
    

    override fun `save`(`databaseKey`: kotlin.String, `epd`: Epd, `json`: kotlin.ByteArray)
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_opening_core_fn_method_statsstore_save(
        it,
        
        FfiConverterString.lower(`databaseKey`),
        FfiConverterTypeEpd.lower(`epd`),
        FfiConverterByteArray.lower(`json`),_status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceStatsStore {
    internal object `load`: UniffiCallbackInterfaceStatsStoreMethod0 {
        override fun callback(`uniffiHandle`: Long,`databaseKey`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeStatsStore.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`load`(
                    FfiConverterString.lift(`databaseKey`),
                )
            }
            val writeReturn = { value: List<StoredStats> -> uniffiOutReturn.setValue(FfiConverterSequenceTypeStoredStats.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `save`: UniffiCallbackInterfaceStatsStoreMethod1 {
        override fun callback(`uniffiHandle`: Long,`databaseKey`: RustBuffer.ByValue,`epd`: RustBuffer.ByValue,`json`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeStatsStore.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`save`(
                    FfiConverterString.lift(`databaseKey`),
                    FfiConverterTypeEpd.lift(`epd`),
                    FfiConverterByteArray.lift(`json`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeStatsStore.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeStatsStore.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceStatsStore.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `load`,
        `save`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_opening_core_fn_init_callback_vtable_statsstore(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeStatsStore: FfiConverter<StatsStore, Long> {
    internal val handleMap = UniffiHandleMap<StatsStore>()

    override fun lower(value: StatsStore): Long {
        if (value is StatsStoreImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): StatsStore {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return StatsStoreImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): StatsStore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: StatsStore) = 8UL

    override fun write(value: StatsStore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


